<template><div class="guest-page"><header class="guest-head"><div class="guest-topline"><span class="eyebrow">JAPANESE KITCHEN · 東京</span><router-link class="history-link" :to="{path:'/guest/history',query:{storeId}}">订单历史</router-link></div><h1>{{store.name}}</h1><p>{{store.tagline}}</p></header><div class="store-notice" :class="{closed:!store.isOpen}"><b>{{store.isOpen?'今日营业中':'暂时停止接单'}}</b><span v-if="store.announcement">{{store.announcement}}</span><span v-if="store.address">地址：{{store.address}}</span><span v-if="store.phone">电话：{{store.phone}}</span></div><CategoryTabs v-model="category"/><section v-if="selectedItems.length" class="guest-order-summary"><div class="summary-heading"><b>已选菜品</b><span>{{count}} 件</span></div><div v-for="item in selectedItems" :key="item.id" class="summary-item"><span>{{item.name}} × {{item.quantity}}</span><b>¥{{item.subtotal.toLocaleString()}}</b></div><div class="summary-total"><span>当前合计</span><strong>¥{{selectedTotal.toLocaleString()}}</strong></div></section><div v-if="loading" class="notice">正在加载菜单…</div><div v-else-if="error" class="notice error">{{error}} <button @click="load">重试</button></div><div v-else-if="visible.length" class="product-grid"><ProductCard v-for="p in visible" :key="p.id" :product="p" :disabled="!store.isOpen"/></div><div v-else class="notice">这个分类暂时没有上架菜品。</div><CartBar :products="products" :open="store.isOpen" :store-id="storeId"/></div></template>
<script setup lang="ts">import {ref,computed,onMounted,watch} from 'vue';import {useRoute} from 'vue-router';import CategoryTabs from '../components/CategoryTabs.vue';import ProductCard from '../components/ProductCard.vue';import CartBar from '../components/CartBar.vue';import {api,type Product,type Store} from '../api';import {cart,count} from '../cart';import {activeStoreId} from '../storeContext';const route=useRoute(),storeId=computed(()=>String(route.query.storeId||activeStoreId.value)),products=ref<Product[]>([]),store=ref<Store>({id:'store-1',name:'Toshio Restaurant',tagline:'',announcement:'',isOpen:true,address:'',phone:''}),category=ref('推荐'),loading=ref(true),error=ref('');const visible=computed(()=>products.value.filter(p=>p.status==='active'&&p.category===category.value).sort((a,b)=>a.sortOrder-b.sortOrder));const selectedItems=computed(()=>products.value.filter(p=>cart[p.id]>0).map(p=>({id:p.id,name:p.name,quantity:cart[p.id],subtotal:p.price*cart[p.id]})));const selectedTotal=computed(()=>selectedItems.value.reduce((sum,item)=>sum+item.subtotal,0));async function load(){loading.value=true;error.value='';try{const [p,s]=await Promise.all([api.get('/products',{params:{storeId:storeId.value}}),api.get('/store',{params:{storeId:storeId.value}})]);products.value=p.data.data;store.value=s.data.data}catch(e:any){error.value=e.message}finally{loading.value=false}}onMounted(load);watch(storeId,async()=>{Object.keys(cart).forEach(k=>delete cart[Number(k)]);await load()});</script>
